import{_ as a,o as e,c as r,ag as l}from"./chunks/framework.CtWPcAmt.js";const g=JSON.parse('{"title":"序章：我为什么写这套教程","description":"作者从「问 AI」到「与 Agent 一起完成任务」的真实转变，以及本教程写给谁、怎么读。","frontmatter":{"title":"序章：我为什么写这套教程","description":"作者从「问 AI」到「与 Agent 一起完成任务」的真实转变，以及本教程写给谁、怎么读。","layout":"doc","lastUpdated":true},"headers":[],"relativePath":"guide/00-preface.md","filePath":"guide/00-preface.md","lastUpdated":null}'),o={name:"guide/00-preface.md"};function i(n,t,d,s,h,c){return e(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="序章-我为什么写这套教程" tabindex="-1">序章：我为什么写这套教程 <a class="header-anchor" href="#序章-我为什么写这套教程" aria-label="Permalink to &quot;序章：我为什么写这套教程&quot;">​</a></h1><h2 id="本章解决什么问题" tabindex="-1">本章解决什么问题 <a class="header-anchor" href="#本章解决什么问题" aria-label="Permalink to &quot;本章解决什么问题&quot;">​</a></h2><p>在你决定花时间学习「AI Agent」之前，先让你知道：这是谁写的、为什么写、他经历过什么、这套教程会把你带到哪里。读完之后，你会写下一个<strong>希望由 Agent 协助完成的真实任务</strong>——这是整本书的第一个产出，也是你真正开始学习的起点。</p><h2 id="从一个真实场景开始" tabindex="-1">从一个真实场景开始 <a class="header-anchor" href="#从一个真实场景开始" aria-label="Permalink to &quot;从一个真实场景开始&quot;">​</a></h2><p>2026 年上半年，我像大多数普通人一样用 AI：打开聊天窗口，问问题，复制答案。遇到「帮我写周报」「查一下这个产品」这类事，我会把需求敲进去，把回复整理一下贴走。效率确实有提升，但始终感觉 AI 只是「更聪明的搜索框」——它不负责把事情做完，收尾的永远是我。</p><p>转折发生在我开始做本教程项目之后。我需要同时处理十几个文档：整理零散材料、核对七款产品的价格、统一格式、生成图表、写体验记录。如果每件事都靠「问一句、抄一段」，这个项目会耗费几周。</p><p>于是我第一次认真使用了桌面 Agent：把材料和任务交给它，让它自己读文件、列计划、写文档、做自检。第一次完整任务跑完时，我意识到自己过去的用法浪费了它九成的能力——<strong>问题不在于 AI 不够强，而在于我从没把它当作一个能执行任务的搭档。</strong></p><p>这之后我经历了更多：一款产品在测试时悄悄读取了工作目录之外的文件；一款产品把文件写错了位置又自己恢复；一款产品的账号被封导致整条工作流中断。这些经历最终沉淀成了你手里的这套教程。</p><h2 id="先说结论" tabindex="-1">先说结论 <a class="header-anchor" href="#先说结论" aria-label="Permalink to &quot;先说结论&quot;">​</a></h2><ol><li><strong>AI Agent 不是「更聪明的聊天框」</strong>，而是一种能接收目标、使用工具、分步执行并交付结果的新工具。会用聊天框不等于会用 Agent；</li><li><strong>普通人完全学得会</strong>。这套教程不假设你会编程、会命令行、懂模型参数——你只需要会打开软件、会拖文件、会读提示；</li><li><strong>「会用」的核心不是记住产品功能，而是学会四件事</strong>：选择适合自己的工具、把任务描述清楚、在安全边界内让它行动、验收它的结果；</li><li><strong>教程的每个概念章都会让你带走一样东西</strong>：任务卡、检查清单、模板、Skill 或一张系统草图。你读完后拥有的不是一个知识库，而是一套自己的工具箱；</li><li><strong>书里写的所有产品体验都有日期和版本</strong>（见第 5、6 章），价格和功能会变，但「如何选择、如何使用、如何验收」的方法不会过时。</li></ol><h2 id="必要概念" tabindex="-1">必要概念 <a class="header-anchor" href="#必要概念" aria-label="Permalink to &quot;必要概念&quot;">​</a></h2><ul><li><strong>AI Agent（智能体）</strong>：能接收任务、自己规划步骤、调用工具并交付结果的 AI 程序。白话理解：一个「会自己干活」的 AI 助手，而不是「只会回答问题」的 AI 客服。第 1 章会详细展开。</li><li><strong>桌面 Agent</strong>：以图形窗口方式运行的 Agent 软件，你能看到界面、按钮和文件，不需要敲命令行。本教程只讲这一类（边界见 <code>../../docs/00-project-brief.md</code>）。</li><li><strong>Harness（工作系统）</strong>：把模型、工具、记忆、权限、验证组织在一起的工作系统。白话理解：给你的 Agent 配一套「工作台 + 规矩 + 检查流程」。这是第五篇的主题，现在不用理解。</li></ul><h2 id="跟着做" tabindex="-1">跟着做 <a class="header-anchor" href="#跟着做" aria-label="Permalink to &quot;跟着做&quot;">​</a></h2><h3 id="第一步-写下你的一个真实任务" tabindex="-1">第一步：写下你的一个真实任务 <a class="header-anchor" href="#第一步-写下你的一个真实任务" aria-label="Permalink to &quot;第一步：写下你的一个真实任务&quot;">​</a></h3><p>拿出一张纸或新建一个文档，写下一个<strong>你最近真的想完成、但一直拖着或觉得麻烦</strong>的任务。不要写「学 AI」这种空目标，要写具体的事，例如：</p><ul><li>把手机里 200 张旅行照片整理成一本带说明的相册；</li><li>把分散在五个文档里的项目信息汇总成一份周报；</li><li>把家里 3 款净水器的参数做成一张对比表，帮我选一款；</li><li>把一篇英文文章翻译成中文并整理成要点。</li></ul><h3 id="第二步-给任务加三个标签" tabindex="-1">第二步：给任务加三个标签 <a class="header-anchor" href="#第二步-给任务加三个标签" aria-label="Permalink to &quot;第二步：给任务加三个标签&quot;">​</a></h3><ul><li><strong>频率</strong>：这是一次性的，还是每周/每月都会重复？</li><li><strong>风险</strong>：做错了会怎样？会损失钱、泄露隐私，还是最多重做一遍？</li><li><strong>材料</strong>：完成它需要哪些文件、链接或信息？它们现在在哪里？</li></ul><h3 id="第三步-保存这张「任务种子」" tabindex="-1">第三步：保存这张「任务种子」 <a class="header-anchor" href="#第三步-保存这张「任务种子」" aria-label="Permalink to &quot;第三步：保存这张「任务种子」&quot;">​</a></h3><p>把它保存为一个文件，命名为「我的第一个任务」。<strong>本书前四篇的所有练习都会围绕它展开</strong>——第 4 章用它选产品，第 7 章用它写任务卡，第 10 章用它验收结果。用真实任务学，比用虚构例子学有效十倍。</p><h2 id="一个完整示例" tabindex="-1">一个完整示例 <a class="header-anchor" href="#一个完整示例" aria-label="Permalink to &quot;一个完整示例&quot;">​</a></h2><p>以我自己为例，我在写这本书之前种下的任务是：</p><blockquote><p>「把散落在十几个文档里的 AI 工具使用经验，整理成一套面向零基础读者的教程框架。」</p></blockquote><p>标签：频率=一次性但后续持续迭代；风险=低（最多推倒重来）；材料=十几个 Markdown 文档、多款产品的截图与记录。</p><p>这个任务后来演变成了你正在读的这本书——它证明了：一个真实任务，加上合适的方法，可以长出远超预期的东西。</p><h2 id="常见错误与恢复方法" tabindex="-1">常见错误与恢复方法 <a class="header-anchor" href="#常见错误与恢复方法" aria-label="Permalink to &quot;常见错误与恢复方法&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>可能原因</th><th>怎样修正</th></tr></thead><tbody><tr><td>写了「我要学 AI」这类空目标</td><td>目标不够具体，无法执行</td><td>换成一件「本周想做完」的具体事情</td></tr><tr><td>任务选得太难（如「做个 App」）</td><td>高估了自己当前的基础</td><td>拆小：先做「用 AI 整理一份需求文档」</td></tr><tr><td>任务涉及隐私或金钱</td><td>没有评估风险</td><td>换成低风险任务起步，风险判断在第 8 章系统学习</td></tr><tr><td>一直找不到「值得做」的任务</td><td>把标准定得太高</td><td>从「最烦的重复劳动」里找，哪怕只是整理收藏夹</td></tr></tbody></table><h2 id="安全提醒" tabindex="-1">安全提醒 <a class="header-anchor" href="#安全提醒" aria-label="Permalink to &quot;安全提醒&quot;">​</a></h2><ul><li>现在不需要把任务告诉任何 AI，也<strong>不要</strong>为了「先试试」就把真实账号、密码或敏感资料发给任何工具；</li><li>如果任务涉及公司文件或他人数据，先确认你是否有权使用；</li><li>本书所有示例均做过脱敏处理，请模仿方法，不要照搬内容。</li></ul><h2 id="本章练习" tabindex="-1">本章练习 <a class="header-anchor" href="#本章练习" aria-label="Permalink to &quot;本章练习&quot;">​</a></h2><p>用 15 分钟完成「跟着做」的三步，写下你的任务种子。如果你已经有明确目标，可以跳到第 4 章选产品；如果你完全没概念，请至少读完第 1、2 章再动手。</p><h2 id="你应该带走的成果" tabindex="-1">你应该带走的成果 <a class="header-anchor" href="#你应该带走的成果" aria-label="Permalink to &quot;你应该带走的成果&quot;">​</a></h2><ul><li><strong>任务种子</strong>：一个真实任务 + 频率/风险/材料三个标签（文件：<code>我的第一个任务.md</code>）。</li></ul><h2 id="本章小结" tabindex="-1">本章小结 <a class="header-anchor" href="#本章小结" aria-label="Permalink to &quot;本章小结&quot;">​</a></h2><ol><li>作者从「问 AI」到「与 Agent 协作」的转变，是这套教程的起点；</li><li>教程面向零基础读者，不要求编程或命令行；</li><li>核心是四件事：选择、描述、安全行动、验收；</li><li>每一章都会让你带走一个可复用成果；</li><li>你现在拥有了第一个成果：一个真实任务。</li></ol>',35)])])}const p=a(o,[["render",i]]);export{g as __pageData,p as default};
